schema_ddl:
CREATE TYPE stato_ordine AS ENUM ('in_attesa', 'processato', 'spedito', 'consegnato', 'annullato');

CREATE TABLE ordini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_ordine DATE NOT NULL,
    stato_ordine stato_ordine NOT NULL DEFAULT 'in_attesa',
    importo_totale NUMERIC(10,2) NOT NULL CHECK (importo_totale >= 0),
    cliente_id INT NOT NULL,
    quantita INT NOT NULL CHECK (quantita > 0),
    prodotto_id INT NOT NULL
);

CREATE INDEX idx_ordini_cliente ON ordini(cliente_id);
CREATE INDEX idx_ordini_prodotto ON ordini(prodotto_id);
